import java.util.Scanner;

public class ParkingLot {
    private int vno;
    private int hours;
    private double bill;

    // Method to accept inputs
    public void input() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Vehicle Registration Number: ");
        vno = sc.nextInt();
        System.out.print("Enter Number of Hours Parked: ");
        hours = sc.nextInt();
    }

    // Method to calculate parking charges
    public void calculate() {
        if (hours <= 1) {
            bill = 3.00;
        } else {
            bill = 3.00 + (hours - 1) * 1.50;
        }
    }

    // Method to display invoice
    public void display() {
        System.out.println("\n====================================");
        System.out.println("        PARKING LOT RECEIPT         ");
        System.out.println("====================================");
        System.out.println("Vehicle Number : " + vno);
        System.out.println("Hours Parked   : " + hours);
        System.out.printf("Total Charge   : Rs. %.2f\n", bill);
        System.out.println("====================================");
    }

    // Main method
    public static void main(String[] args) {
        ParkingLot ticket = new ParkingLot();
        ticket.input();
        ticket.calculate();
        ticket.display();
    }
}
