import java.util.Scanner;

public class MatrixRowMaxAndSum {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] mat = new int[4][4];

        System.out.println("Enter 16 integers for a 4x4 matrix:");
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                mat[i][j] = sc.nextInt();
            }
        }

        // Display Matrix
        System.out.println("\n--- Given 4x4 Matrix ---");
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                System.out.print(mat[i][j] + "\t");
            }
            System.out.println();
        }

        int totalSum = 0;

        System.out.println("\n--- Row-wise Maximums ---");
        for (int i = 0; i < 4; i++) {
            int rowMax = mat[i][0];
            for (int j = 0; j < 4; j++) {
                totalSum += mat[i][j];
                if (mat[i][j] > rowMax) {
                    rowMax = mat[i][j];
                }
            }
            System.out.println("Maximum element of Row " + (i + 1) + ": " + rowMax);
        }

        System.out.println("\nTotal Sum of all matrix elements = " + totalSum);
        sc.close();
    }
}
```

