public class SeriesOverload {
    // Method 1: sum of series x/1 + x/2 + ... + x/n
    public double series(double x, int n) {
        double sum = 0.0;
        for (int i = 1; i <= n; i++) {
            sum += x / i;
        }
        return sum;
    }

    // Method 2: sum of series 1/1! + 1/2! + ... + 1/p!
    public double series(int p) {
        double sum = 0.0;
        long fact = 1;
        for (int i = 1; i <= p; i++) {
            fact *= i;
            sum += 1.0 / fact;
        }
        return sum;
    }

    // Method 3: print number triangle pattern
    public void series() {
        System.out.println("Pattern:");
        for (int i = 1; i <= 5; i++) {
            for (int j = 1; j <= i; j++) {
                System.out.print(j + " ");
            }
            System.out.println();
        }
    }

    public static void main(String[] args) {
        SeriesOverload obj = new SeriesOverload();

        System.out.println("Call 1: series(2.0, 5) =");
        double s1 = obj.series(2.0, 5);
        System.out.printf("Sum = %.4f\n\n", s1);

        System.out.println("Call 2: series(4) =");
        double s2 = obj.series(4);
        System.out.printf("Sum = %.4f\n\n", s2);

        System.out.println("Call 3: series() =");
        obj.series();
    }
}
```

